  ami           = var.ami_id
  instance_type = var.instance_type
  tags = {
    Name = "web-server"
  }
}

variable "aws_region" {
  type    = string
  default = "us-west-2"
}

variable "instance_type" {
  type = string
}

output "public_ip" {
  value = aws_instance.web.public_ip
}

module "network" {
  source      = "./modules/network"
  cidr_block  = var.vpc_cidr
  environment = var.environment
}

